import numpy as np

def pack():
    n = 26
    best = None
    def compositions(rem, rows):
        if rows == 1:
            if 3 <= rem <= 8:
                yield [rem]
            return
        for c in range(3, 9):
            if c < rem and 3 * (rows - 1) <= rem - c <= 8 * (rows - 1):
                for rest in compositions(rem - c, rows - 1):
                    yield [c] + rest
    for R in range(4, 7):
        dy = 1.0 / R
        ys = [(i + 0.5) * dy for i in range(R)]
        for counts in compositions(n, R):
            maxc = max(counts)
            dx = 1.0 / maxc
            for stagger in (0.0, 0.5):
                centers = []
                for i, c in enumerate(counts):
                    off = stagger * dx if i % 2 else 0.0
                    for j in range(c):
                        x = 0.5 + (j - (c - 1) / 2) * dx + off
                        centers.append((x, ys[i]))
                centers = np.array(centers)
                if np.any(centers[:, 0] < 0) or np.any(centers[:, 0] > 1):
                    continue
                d = np.sqrt(((centers[:, None, :] - centers[None, :, :]) ** 2).sum(-1))
                d += np.eye(n) * 1e9
                r = d.min() / 2
                wall = np.minimum(np.minimum(centers[:, 0], 1 - centers[:, 0]), np.minimum(centers[:, 1], 1 - centers[:, 1])).min()
                r = min(r, wall)
                if best is None or r > best[0]:
                    best = (r, centers.copy())
    r, centers = best
    radii = np.full(n, r * (1 - 1e-7) - 1e-12)
    return centers, radii

