def pack():
    n = 26
    def build(p):
        d1, d2, o1, o2 = p
        c = [(0.5, 0.5)]
        for i in range(8):
            a = 2 * np.pi * i / 8 + o1
            c.append((0.5 + d1 * np.cos(a), 0.5 + d1 * np.sin(a)))
        for i in range(17):
            a = 2 * np.pi * i / 17 + o2
            c.append((0.5 + d2 * np.cos(a), 0.5 + d2 * np.sin(a)))
        return np.array(c, dtype=float)
    def radii(c):
        d = np.sqrt(((c[:, None, :] - c[None, :, :]) ** 2).sum(-1)) + np.eye(n) * 1e9
        r = d.min(1) * 0.5
        b = np.minimum(np.minimum(c[:, 0], 1 - c[:, 0]), np.minimum(c[:, 1], 1 - c[:, 1]))
        return np.minimum(r, b)
    def obj(p):
        if not (0.05 < p[0] < 0.45 and 0.1 < p[1] < 0.49):
            return 1e3
        return -radii(build(p)).sum()
    x0 = np.array([0.30, 0.45, 0.0, 0.0])
    res = minimize(obj, x0, method="Nelder-Mead", options={"maxiter": 400, "xatol": 1e-4, "fatol": 1e-6})
    c = build(res.x)
    r = radii(c) * (1 - 1e-7)
    return c, r

