        r = np.minimum(np.array(r, float).copy(), np.minimum(np.minimum(xy[:,0], 1-xy[:,0]), np.minimum(xy[:,1], 1-xy[:,1])))
        d = xy[pi] - xy[pj]; dist = np.sqrt(np.sum(d*d, 1))
        for _ in range(120):
            np.minimum.at(r, pi, np.maximum(dist - r[pj], 0)); np.minimum.at(r, pj, np.maximum(dist - r[pi], 0))
