        xy = np.zeros((n,2))
        for k in range(h): xy[2*k] = pts[k]; xy[2*k+1] = (1-pts[k,0], pts[k,1])
        return xy
    rng = np.random.default_rng(7); best_xy = best_r = None; best_s = -1
    starts = [grid_start(rng,0), grid_start(rng,0.03), grid_start(rng,0.06)]
