        xy, r, sc = refine(s, 0.085, 280)
        if sc > best_s: best_s, best_xy, best_r = sc, xy, r
    cur_xy, cur_r = best_xy, best_r
    while time.time() - t0 < 2.3:
        scale = rng.uniform(0.01, 0.05)
